    public static function questions(array $cats, int $count, int $seed): array {
        $pool = array_values(array_filter(self::Q, function ($q) use ($cats) { return !$cats || in_array($q[0], $cats, true); }));
        mt_srand($seed); $out = [];
        for ($i = count($pool) - 1; $i > 0; $i--) { $j = mt_rand(0, $i); $t = $pool[$i]; $pool[$i] = $pool[$j]; $pool[$j] = $t; }
        foreach (array_slice($pool, 0, $count) as $q) $out[] = self::make('bank', $q[0], $q[1], $q[2], [$q[3], $q[4], $q[5]], mt_rand());
        mt_srand();
        return $out;
    }
    public static function make(string $source, string $cat, string $q, string $correct, array $wrong, int $seed): array {
        $choices = array_merge([$correct], array_slice(array_values($wrong), 0, 3));
        $order = [0, 1, 2, 3]; usort($order, function ($a, $b) use ($seed) { return crc32($seed . ':' . $a) <=> crc32($seed . ':' . $b); });
        $c = []; $answer = 0;
        foreach ($order as $i => $o) { $c[] = $choices[$o]; if ($o === 0) $answer = $i; }
        return ['source' => $source, 'category' => $cat, 'question' => $q, 'choices' => $c, 'answer' => $answer];
    }
